use semio_framework_test_fixtures::fixture_text;
use super::*;
struct Construction{grant:RetainedCloneGrant,spent:RetainedCloneProgress}
impl NativeDecodeConstructionRecipient for Construction{fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{if !semio_framework_value::retained_clone::retained_clone_grant_admits(self.grant,d){return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"original fixture construction denied"));}Ok(self.grant)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(p.fits(g));self.spent=self.spent.checked_add(p)?;Ok(())}}
#[test]
fn original_job_receiving_preserves_ledger_recipient_and_cumulative_capacity(){
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../🛬️receiving/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){let mut owner=OriginalJobDecodeOwner::empty();let mut identity=None;let mut recipient=None;let cancelled=case["cancelled"].as_bool().unwrap();let mut callback=|_:NativeDecodeProgress|!cancelled;
  for capacity in case["turnCapacity"].as_array().unwrap(){let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:capacity.as_u64().unwrap()as usize,maximum_release_bytes:4096,maximum_depth:16};let mut construction=Construction{grant,spent:Default::default()};let result=owner.receive(grant,&mut callback,&mut construction,|control|{if let Some(original)=identity{assert_eq!(control.ledger_identity(),original);}else{identity=Some(control.ledger_identity());}if let Some(original)=recipient{assert_eq!(control.retirement_recipient_identity(),Some(original));}else{recipient=control.retirement_recipient_identity();}control.copy_text(case["text"].as_str().unwrap())});if cancelled{assert_eq!(result.unwrap_err().kind,ValueRefusalKind::Canceled);}else{let actual=result.unwrap();assert_eq!(serde_json::to_value(&actual).unwrap(),case["text"]);let bytes=actual.capacity();let close=RetainedCloneGrant{maximum_release_bytes:bytes,..grant};semio_framework_value::advance_retirement_turn(RetirementDemand{release_bytes:bytes,depth:1,..Default::default()},close,|_|{drop(actual);Ok::<_,ValueError>((RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,released_bytes:bytes,..Default::default()}),true))}).unwrap();}}
  assert_eq!(owner.owned_bytes(),case["expectedOwned"].as_u64().unwrap()as usize);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:16};while !owner.terminal_is_empty(){assert!(owner.close_step(grant).unwrap().progress().fits(grant));}assert!(owner.terminal_is_empty());
 }eprintln!("[DEBUG] original Job receiving scalar ledger and exact recipient persist across caller turns, Unicode/NUL bytes match Serde/SQLite, original cancellation closes terminal");
}
#[test]
fn original_context_charges_child_construction_and_enclosing_semantic_once(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../🛬️receiving/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let law=&fixture["receiptLaw"];assert_eq!(law["childCopy"].as_u64().unwrap()+law["parentCopy"].as_u64().unwrap(),law["expectedCopy"].as_u64().unwrap());assert_eq!(law["childCapacity"],law["expectedCapacity"]);
 use crate::{CancelToken,StepContext,StepBudget,OperationId,Generation};use semio_framework_job_payload::JobPayloadAuthority;use semio_framework_value::retirement::controlled::ControlledRetirement;
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let(mut cancel,_)=CancelToken::admit_root(grant).unwrap().unwrap();let(mut payload,_)=JobPayloadAuthority::admit(OperationId(71),Generation(3),grant).unwrap().unwrap();let mut owner=OriginalJobDecodeOwner::empty();let mut sequence=0;let mut spent=RetainedCloneProgress::default();let mut output=None;
 for _ in 0..2{let mut raw=Some(String::from("π\0🌿"));let mut cx=StepContext::with_payload_authority(OperationId(71),Generation(3),StepBudget::new(4,u64::MAX,grant),&cancel,crate::logical_now_us,&mut sequence,&mut spent,&payload).unwrap().with_original_decoder(&mut owner);let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_native_receiving(|control|control.receive_shared(&mut raw,&mut output,semio_framework_value::retirement::shared::sealed::SharedIssuer::owned())).unwrap());assert_eq!(heap.requested_bytes,p.retained_capacity_bytes);assert_eq!(cx.receiving_child_progress(),p);let mut enclosing=p;enclosing.copied_bytes+=law["parentCopy"].as_u64().unwrap()as usize;cx.consume_receiving_retained(grant,enclosing).unwrap();assert_eq!(cx.retained_progress(),enclosing);assert_eq!(cx.receiving_child_progress(),Default::default());drop(cx);spent=Default::default();let original=output.take().unwrap();let mut close=ControlledRetirement::new(original).map_err(|(e,_)|e).unwrap();while !close.terminal_is_empty(){close.step(grant).unwrap();}}
 while !owner.terminal_is_empty(){owner.close_step(grant).unwrap();}while !payload.terminal_is_empty(){payload.close_step(grant).unwrap();}let mut root=semio_framework_async::CancelTokenRetirement::from_token(cancel);while !root.terminal_is_empty(){root.close_step(grant).unwrap();}eprintln!("[DEBUG] original StepContext construction child and enclosing semantic receipt debit same caller once, exact heap and funded original authorities close");
}
fn retire_original_text(raw:&mut Option<String>,close:&mut semio_framework_value::retained_clone::RetainedCloneClose,control:&mut semio_framework_value_native_owned::native_decoding::NativeRetirementDecodeControl<'_, '_>,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{
 if raw.is_none()&&close.is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}let demand=close.next_owner_demands::<String>(raw.is_some(),&None,grant.maximum_copy_bytes)?;if !semio_framework_value::retained_clone::retained_clone_grant_admits(grant,demand){return Ok(RetainedCloneStep::Progress(Default::default()));}control.charge(demand.capacity_bytes)?;if !close.is_empty(){close.step_granted(grant)}else{close.begin_granted(raw,grant)?.ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original text retirement omitted its funded frame"))}
}
#[test]
fn original_context_retirement_after_cancel_keeps_ledger_deadline_fuel_and_exact_heap(){
 use crate::{CancelToken,StepContext,StepBudget,OperationId,Generation};use semio_framework_job_payload::JobPayloadAuthority;
 let corpus:serde_json::Value=serde_json::from_str(fixture_text!("../../🛬️receiving/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for case in corpus["retirementCases"].as_array().unwrap(){
  let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:4096,maximum_depth:64};let(cancel,_)=CancelToken::admit_root(grant).unwrap().unwrap();let(mut payload,_)=JobPayloadAuthority::admit(OperationId(75),Generation(4),grant).unwrap().unwrap();let mut owner=OriginalJobDecodeOwner::empty();let mut observer=|_:NativeDecodeProgress|true;let mut construction=Construction{grant,spent:Default::default()};let mut original_ledger=None;let mut original_recipient=None;let mut raw=Some(owner.receive(grant,&mut observer,&mut construction,|control|{original_ledger=Some(control.ledger_identity());original_recipient=control.retirement_recipient_identity();control.copy_text("π\0🌿")}).unwrap());assert_eq!(serde_json::to_value(raw.as_ref().unwrap()).unwrap(),serde_json::json!("π\0🌿"));if case["cancelled"].as_bool().unwrap(){cancel.cancel_now();}
  let mut sequence=0;let mut spent=Default::default();let mut close=semio_framework_value::retained_clone::RetainedCloneClose::default();let visited=std::cell::Cell::new(false);let admitted=owner.owned_bytes();
  {let deadline=if case["deadlineOpen"].as_bool().unwrap(){u64::MAX}else{0};let mut cx=StepContext::with_payload_authority(OperationId(75),Generation(4),StepBudget::new(case["fuel"].as_u64().unwrap(),deadline,grant),&cancel,crate::logical_now_us,&mut sequence,&mut spent,&payload).unwrap().with_original_decoder(&mut owner);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_native_retirement(|control|{visited.set(true);assert_eq!(Some(control.ledger_identity()),original_ledger);assert_eq!(control.retirement_recipient_identity(),original_recipient);retire_original_text(&mut raw,&mut close,control,grant)}));assert_eq!(visited.get(),case["visited"].as_bool().unwrap());match result{Ok(step)=>{let p=step.progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));cx.consume_retained(p).unwrap();cx.consume_fuel(p.copied_items as u64);},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}}}
  assert_eq!(owner.owned_bytes()-admitted,spent.retained_capacity_bytes);
  while raw.is_some()||!close.is_empty(){spent=Default::default();let admitted=owner.owned_bytes();let mut cx=StepContext::with_payload_authority(OperationId(75),Generation(4),StepBudget::new(1,u64::MAX,grant),&cancel,crate::logical_now_us,&mut sequence,&mut spent,&payload).unwrap().with_original_decoder(&mut owner);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_native_retirement(|control|{assert_eq!(Some(control.ledger_identity()),original_ledger);assert_eq!(control.retirement_recipient_identity(),original_recipient);retire_original_text(&mut raw,&mut close,control,grant)}).unwrap());let p=step.progress();assert!(p.fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));cx.consume_retained(p).unwrap();cx.consume_fuel(p.copied_items as u64);drop(cx);assert_eq!(owner.owned_bytes()-admitted,p.retained_capacity_bytes);}
  while !owner.terminal_is_empty(){owner.close_step(grant).unwrap();}while !payload.terminal_is_empty(){payload.close_step(grant).unwrap();}let mut root=semio_framework_async::CancelTokenRetirement::from_token(cancel);while !root.terminal_is_empty(){root.close_step(grant).unwrap();}
 }eprintln!("[DEBUG] original StepContext retirement closes born Unicode custody after cancel, preserves ledger/recipient, rejects expired deadline and empty fuel, every physical receipt matches System heap");
}